subsequentTestCommands:
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createRouter } from './src/index.mjs';
const input = {
  defaults: { enabled: true, timeout: 10, label: 'default', headers: { a: 'one', b: 'two' } },
  routes: [
    { id: 'catchall', pattern: '*', settings: { target: 'catchall' } },
    { id: 'app-first', pattern: '/app/*', settings: { label: 'app' } },
    { id: 'exact', pattern: '/app', settings: { enabled: false, target: 'exact' } },
    { id: 'admin', pattern: '/app/admin/*', settings: { target: 'admin' } },
    { id: 'app-second', pattern: '/app/*', settings: { target: 'wrong-tie' } },
  ],
};
const router = createRouter(input);
input.defaults.timeout = 99;
input.routes[3].settings.target = 'mutated';
router.setTenant('red', { timeout: 0, label: '', headers: { a: null, c: '' } });
const red = router.resolve('red', '/app/admin/x');
assert.equal(red.route, 'admin');
assert.equal(red.target, 'admin');
assert.equal(red.enabled, true);
assert.equal(red.timeout, 0);
assert.equal(red.label, '');
assert.deepEqual(red.headers, { b: 'two', c: '' });
red.headers.b = 'mutated';
assert.equal(router.resolve('red', '/app/admin/x').headers.b, 'two');
assert.equal(router.resolve('blue', '/app/admin/x').timeout, 10);
assert.equal(router.resolve('blue', '/app').route, 'exact');
assert.equal(router.resolve('blue', '/app').enabled, false);
assert.equal(router.resolve('blue', '/app/item').route, 'app-first');
assert.equal(router.resolve('blue', '/apple').route, 'catchall');
router.setTenant('red', { timeout: 5 });
assert.equal(router.resolve('red', '/app/admin/x').timeout, 5);
assert.equal(router.resolve('red', '/app/admin/x').headers.a, 'one');
console.log('contract checks passed');
EOF

