export function mergeFields(result, layer) {
  for (const [key, value] of Object.entries(layer)) {
    if (key !== 'headers' && value) result[key] = value;
  }
}

patches.after:
export function mergeFields(result, layer) {
  for (const [key, value] of Object.entries(layer)) {
    if (key !== 'headers') result[key] = value;
  }
}

export function mergeHeaders(base, overrides) {
  const result = { ...base };
  for (const [name, value] of Object.entries(overrides)) {
    if (value === null) {
      delete result[name];
    } else {
      Object.defineProperty(result, name, {
        value,
        enumerable: true,
        configurable: true,
        writable: true,
      });
    }
  }
  return result;
}

